#!/usr/bin/env python3
"""Generate site/data/parts.json (catalogue of electronic parts, no prices)."""
import json, re, os
OUT = os.path.join(os.path.dirname(__file__), '..', 'site', 'data', 'parts.json')
CM = 'https://commons.wikimedia.org/wiki/Special:FilePath/'
def img(fn): return CM + fn + '?width=600'
def src(fn): return 'https://commons.wikimedia.org/wiki/File:' + fn
FAM = {  # family -> Commons file (names confirmed by search)
 'ultrasonic': 'HC_SR04_Ultrasonic_Module.jpg',
 'dht': 'Dht11_term_and_humidity_sensor.jpg',
 'mpu': 'GY-521_MPU-6050_Module_3_Axis_Gyroscope_+_Accelerometer_0487.jpg',
 'servo': 'Tower_Pro_SG90_micro_servo_motor.jpg',
 'lcd': '16x2_Character_LCD_Display.jpg',
 'breadboard': 'Solderless_Breadboard_with_LEDs.jpg',
 'jumper': 'A_few_Jumper_Wires.jpg',
 'nodemcu': 'NodeMCU_DEVKIT_1.0.jpg',
 'espcam': 'ESP32-CAM.jpg',
}
parts = []; seen = set()
def add(cat, name, spec, desc, pkg='', fam=None, tags=''):
    pid = re.sub(r'[^a-z0-9]+', '-', (cat + ' ' + name).lower()).strip('-')
    if pid in seen: return
    seen.add(pid)
    d = {'id': 'p-' + pid, 'name': name, 'category': cat, 'package': pkg, 'specs': spec, 'description': desc, 'tags': tags, 'price': None, 'unit': 'piece'}
    if fam: d['image'] = img(FAM[fam]); d['imageSource'] = src(FAM[fam])
    parts.append(d)

def eng(v):
    for s, m in (('M', 1e6), ('k', 1e3), ('', 1)):
        if v >= m: x = v / m; return (('%g' % round(x, 2)) + s).replace('.', s if s else '.') if s and '.' in ('%g' % round(x,2)) else ('%g' % round(x, 2)) + s
    return '%g' % v
def efmt(v, unit):
    for s, m in (('M', 1e6), ('k', 1e3), ('', 1)):
        if v >= m: return ('%g' % round(v / m, 3)) + s + unit
def cfmt(pf):
    if pf >= 1e6: return '%g µF' % (pf / 1e6)
    if pf >= 1e3: return '%g nF' % (pf / 1e3)
    return '%g pF' % pf
E24 = [1.0,1.1,1.2,1.3,1.5,1.6,1.8,2.0,2.2,2.4,2.7,3.0,3.3,3.6,3.9,4.3,4.7,5.1,5.6,6.2,6.8,7.5,8.2,9.1]
E12 = [1.0,1.2,1.5,1.8,2.2,2.7,3.3,3.9,4.7,5.6,6.8,8.2]
def decades(series, lo, hi):
    out = []
    d = lo
    while d <= hi:
        for m in series:
            v = round(m * d, 2)
            if v <= hi: out.append(v)
        d *= 10
    return out

